import{_ as a,c as t,o as r,al as i}from"./chunks/framework.CT7RwC5a.js";const m=JSON.parse('{"title":"IMU, AHRS, and INS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sensor/inertial_navigation_systems.md","filePath":"zh/sensor/inertial_navigation_systems.md"}'),o={name:"zh/sensor/inertial_navigation_systems.md"};function n(s,e,l,d,h,c){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="imu-ahrs-and-ins" tabindex="-1">IMU, AHRS, and INS <a class="header-anchor" href="#imu-ahrs-and-ins" aria-label="Permalink to &quot;IMU, AHRS, and INS&quot;">​</a></h1><p>PX4 typically runs on flight controllers that include an IMU, such as the Pixhawk series, and fuse the sensor data along with GNSS information in the EKF2 estimator to determine vehicle attitude, heading, position, and velocity.</p><p>However PX4 can also use some INS devices as either sources of raw data, or as an external estimator, replacing EKF2.</p><h2 id="supported-ins-systems" tabindex="-1">Supported INS Systems <a class="header-anchor" href="#supported-ins-systems" aria-label="Permalink to &quot;Supported INS Systems&quot;">​</a></h2><p>INS systems that can be used as a replacement for EKF2 in PX4:</p><ul><li><a href="./../sensor/inertiallabs.html">InertialLabs</a></li><li><a href="./../sensor/sbgecom.html">SBG Systems</a>: IMU/AHRS, GNSS/INS, Dual GNSS/INS systems that can be used as an external INS or as a source of raw sensor data.</li><li><a href="./../sensor/vectornav.html">VectorNav</a>: IMU/AHRS, GNSS/INS, Dual GNSS/INS systems that can be used as an external INS or as a source of raw sensor data.</li></ul><h2 id="px4-firmware" tabindex="-1">PX4 Firmware <a class="header-anchor" href="#px4-firmware" aria-label="Permalink to &quot;PX4 Firmware&quot;">​</a></h2><p>The driver module for your INS system may not be included in the PX4 firmware for your flight controller by default.</p><p>You can check by searching the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6c/default.px4board#L25" target="_blank" rel="noreferrer">default.px4board</a> configuration file for your target board for either:</p><ul><li><code>CONFIG_COMMON_INS</code>, which includes drivers for <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/drivers/ins/Kconfig" target="_blank" rel="noreferrer">all INS systems</a>.</li><li>The key for the particular INS system you are using, such as: <ul><li><code>CONFIG_DRIVERS_INS_ILABS</code></li><li><code>CONFIG_DRIVERS_INS_MICROSTRAIN</code></li><li><code>CONFIG_DRIVERS_INS_VECTORNAV</code></li></ul></li></ul><p>If the required key is not present you can include the module in firmware by adding the key to the <code>default.px4board</code> file, or using the <a href="./../hardware/porting_guide_config.html#px4-board-configuration-kconfig">kconfig board configuration tool</a> and then select the driver you want (<code>Drivers -&gt; INS</code>). Note that if you&#39;re working on a flight controller where flash memory is limited, you&#39;re better off installing just the modules you need.</p><p>You will then need to rebuild the firmware.</p><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><h3 id="inertial-measurement-unit-imu" tabindex="-1">Inertial Measurement Unit (IMU) <a class="header-anchor" href="#inertial-measurement-unit-imu" aria-label="Permalink to &quot;Inertial Measurement Unit (IMU)&quot;">​</a></h3><p>An IMU is a device that contains a 3-axis accelerometer (motion sensor), 3-axis gyroscope (rotation sensor), and sometimes a magnetometer (compass). The gyroscope and accelerometer provide raw sensor data that allow measurement of a system&#39;s angular rate and acceleration. The magnetometer, if present, provides sensor data that can be used to provide the direction that the vehicle is facing/heading.</p><h3 id="attitude-heading-reference-system-ahrs" tabindex="-1">Attitude Heading Reference System (AHRS) <a class="header-anchor" href="#attitude-heading-reference-system-ahrs" aria-label="Permalink to &quot;Attitude Heading Reference System (AHRS)&quot;">​</a></h3><p>An AHRS system that includes both an IMU and a processing system that can provide attitude and heading information from the IMUs raw data.</p><h3 id="inertial-navigation-system-ins" tabindex="-1">Inertial Navigation System (INS) <a class="header-anchor" href="#inertial-navigation-system-ins" aria-label="Permalink to &quot;Inertial Navigation System (INS)&quot;">​</a></h3><p>An INS is a navigation device that uses accelerometers, gyroscopes, possibly magnetometers, and a computer to calculate the attitude, position, and velocity of a moving object without the need for external references. Essentially it is an AHRS that also includes position/velocity estimation.</p><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="https://www.vectornav.com/resources/inertial-navigation-articles/what-is-an-ins" target="_blank" rel="noreferrer">What is an Inertial Navigation System?</a> (VectorNav)</li><li><a href="https://www.vectornav.com/resources/inertial-navigation-primer" target="_blank" rel="noreferrer">Inertial Navigation Primer</a> (VectorNav)</li></ul>',21)]))}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
